package com.autocare.platform.order;
import com.autocare.platform.ai.DeepSeekClient;
import com.autocare.platform.gateway.identity.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class JdbcLicensedKnowledgeTest extends JdbcCommunityQuestionsTest {
 LicensedKnowledge knowledge;DeepSeekClient ai;
 @BeforeEach void knowledgeSetup(){jdbc.execute("DROP TRIGGER IF EXISTS reject_knowledge_audit");jdbc.update("DELETE FROM knowledge_document_event");jdbc.update("DELETE FROM knowledge_document");jdbc.update("UPDATE operator_account SET can_knowledge=1 WHERE id=1");ai=mock(DeepSeekClient.class);when(ai.configured()).thenReturn(true);knowledge=new LicensedKnowledge(db,policies.operators,new ExperienceModeration(db,policies.operators,false),ai,true,true);}
 @AfterEach void knowledgeCleanup(){jdbc.execute("DROP TRIGGER IF EXISTS reject_knowledge_audit");}
 ObjectNode config(){return json.createObjectNode().put("title","合成冷却液资料").put("publisher","合成出版者").put("document_version","synthetic-v1").put("source_reference","synthetic-source-not-a-real-manual").put("license_reference","private-synthetic-license-proof").put("license_confirmed",true).put("model_id",1).put("valid_from",clock.value.minusSeconds(60).toString()).put("valid_to",clock.value.plusSeconds(3600).toString()).put("search_allowed",true).put("excerpt_allowed",true).put("ai_allowed",true).put("body","冷却液检查资料仅为合成测试。需要到店核查，不表示车辆诊断。");}
 long createKnowledge(ObjectNode b){KnowledgeInput.config(b.toString(),false);return knowledge.save(manager,null,key(),b).path("data").path("id").asLong();}
 ObjectNode state(long revision,String status){return json.createObjectNode().put("expected_revision",revision).put("status",status);}
 String publishKnowledge(long id){knowledge.status(manager,id,key(),state(1,"PUBLISHED"));return jdbc.queryForObject("SELECT public_id FROM knowledge_document WHERE id=?",String.class,id);}
 @Test void knowledgePermissionIsIndependentAndDefaultOff(){jdbc.update("UPDATE operator_account SET can_knowledge=0 WHERE id=1");assertEquals(403,code(()->knowledge.admin(manager,1)));jdbc.update("UPDATE operator_account SET can_knowledge=1,can_catalog=0,can_review=0 WHERE id=1");assertEquals(0L,knowledge.admin(manager,1).get("total"));assertEquals(403,code(()->knowledge.admin(first,1)));}
 @Test void licenseAndExcerptMustBeConfirmedBeforePublication(){long id=createKnowledge(config().put("license_confirmed",false));assertEquals(409,code(()->knowledge.status(manager,id,key(),state(1,"PUBLISHED"))));var b=config().put("expected_revision",1).put("excerpt_allowed",false);knowledge.save(manager,id,key(),b);assertEquals(409,code(()->knowledge.status(manager,id,key(),state(2,"PUBLISHED"))));assertEquals(400,code(()->KnowledgeInput.config(config().put("license_confirmed","true").toString(),false)));}
 @Test void draftUnknownPublishedSearchAndCitationAreReadOnlyAndMinimal(){long id=createKnowledge(config());assertEquals("UNKNOWN",knowledge.search(owner,1,"冷却液",null).get("state"));String reference=publishKnowledge(id);int audits=count("audit_log"),events=count("knowledge_document_event");var result=json.valueToTree(knowledge.search(peer,2,"冷却液",null));assertEquals("KEYWORD",result.path("method").asText());assertEquals(reference,result.path("items").get(0).path("reference").asText());assertFalse(result.toString().contains("license_reference"));assertFalse(result.toString().contains("private-synthetic"));var detail=json.valueToTree(knowledge.detail(peer,2,reference));assertTrue(detail.path("document").path("body").asText().contains("合成测试"));assertEquals(audits,count("audit_log"));assertEquals(events,count("knowledge_document_event"));}
 @Test void publicDetailsRemainBoundToCurrentOwnerAndExactModel(){String reference=publishKnowledge(createKnowledge(config()));assertEquals(404,code(()->knowledge.detail(owner,2,reference)));jdbc.update("INSERT INTO model(id,series_id,year,config_name,status) VALUES(2,1,'2027','different synthetic model',1)");jdbc.update("UPDATE vehicle SET model_id=2 WHERE id=2");assertEquals(404,code(()->knowledge.detail(peer,2,reference)));jdbc.update("UPDATE knowledge_document SET model_id=2");assertEquals(404,code(()->knowledge.detail(peer,2,reference)));}
 @Test void futureExpiryAndStoppedSourcesCannotBeReadOrRepublished(){var b=config().put("valid_from",clock.value.plusSeconds(10).toString());long id=createKnowledge(b);String reference=publishKnowledge(id);assertEquals(404,code(()->knowledge.detail(peer,2,reference)));clock.value=clock.value.plusSeconds(11);assertNotNull(knowledge.detail(peer,2,reference));knowledge.status(manager,id,key(),state(2,"STOPPED"));assertEquals(404,code(()->knowledge.detail(peer,2,reference)));assertEquals(409,code(()->knowledge.status(manager,id,key(),state(3,"PUBLISHED"))));}
 @Test void modifiedPayloadSoftDeletedAuditAndOldRowRollbackAreHidden(){long id=createKnowledge(config());String reference=publishKnowledge(id);jdbc.update("UPDATE knowledge_document SET payload=JSON_SET(payload,'$.body','replaced private body') WHERE id=?",id);assertEquals(404,code(()->knowledge.detail(peer,2,reference)));jdbc.update("UPDATE knowledge_document SET payload=? WHERE id=?",db.json(config()),id);assertNotNull(knowledge.detail(peer,2,reference));knowledge.status(manager,id,key(),state(2,"STOPPED"));jdbc.update("UPDATE knowledge_document SET status='PUBLISHED',revision=2 WHERE id=?",id);assertEquals(404,code(()->knowledge.detail(peer,2,reference)));}
 @Test void permanentCreationReceiptDoesNotDuplicateAfterExpiryOrUnavailableModel(){var b=config();String request=key();var result=knowledge.save(manager,null,request,b);jdbc.update("DELETE FROM idempotency_record");jdbc.update("UPDATE model SET status=0 WHERE id=1");assertEquals(result.path("data"),knowledge.save(manager,null,request,b).path("data"));assertEquals(1,count("knowledge_document"));assertEquals(400,code(()->knowledge.save(manager,null,request,b.deepCopy().put("title","different"))));}
 @Test void auditFailureRollsBackDocumentAndEventTogether(){var b=config();String request=key();jdbc.execute("CREATE TRIGGER reject_knowledge_audit BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");assertEquals(503,code(()->knowledge.save(manager,null,request,b)));assertEquals(0,count("knowledge_document"));assertEquals(0,count("knowledge_document_event"));jdbc.execute("DROP TRIGGER reject_knowledge_audit");knowledge.save(manager,null,request,b);assertEquals(1,count("knowledge_document_event"));}
 @Test void concurrentPublicationHasOneWinner()throws Exception{long id=createKnowledge(config());var pool=Executors.newFixedThreadPool(2);try{var gate=new CountDownLatch(1);var x=pool.submit(()->{gate.await();return code(()->knowledge.status(manager,id,key(),state(1,"PUBLISHED")));});var y=pool.submit(()->{gate.await();return code(()->knowledge.status(manager,id,key(),state(1,"PUBLISHED")));});gate.countDown();var result=new ArrayList<>(List.of(x.get(30,TimeUnit.SECONDS),y.get(30,TimeUnit.SECONDS)));Collections.sort(result);assertEquals(List.of(200,409),result);}finally{pool.shutdownNow();}}
 @Test void searchTreatsSqlPayloadAndWildcardsAsData(){publishKnowledge(createKnowledge(config()));assertTrue(((List<?>)knowledge.search(owner,1,"' OR 1=1 --",null).get("items")).isEmpty());assertTrue(((List<?>)knowledge.search(owner,1,"%_",null).get("items")).isEmpty());assertEquals(1,count("knowledge_document"));}
 @Test void aiOnlyReceivesLicensedPublicExcerptsAndProvidesCurrentReferences(){String reference=publishKnowledge(createKnowledge(config()));when(ai.complete(anyString(),anyList(),anyInt())).thenAnswer(invocation->{String system=invocation.getArgument(0);List<DeepSeekClient.Message> turns=invocation.getArgument(1);assertFalse(system.contains("synthetic-source"));assertFalse(turns.toString().contains("license_reference"));assertFalse(turns.toString().contains("private-vin"));return new DeepSeekClient.Completion("合成参考回答，请到店检查。","synthetic-model",1,1);});var result=json.valueToTree(knowledge.answer(owner,json.createObjectNode().put("vehicle_id",1).put("question","冷却液检查")));assertEquals(reference,result.path("provided_sources").get(0).path("reference").asText());assertEquals("KEYWORD",result.path("method").asText());}
 @Test void aiConsentIsSeparateAndRevocationDuringUpstreamCallDiscardsAnswer(){long first=createKnowledge(config().put("ai_allowed",false));publishKnowledge(first);var request=json.createObjectNode().put("vehicle_id",1).put("question","冷却液检查");assertEquals(409,code(()->knowledge.answer(owner,request)));verify(ai,never()).complete(anyString(),anyList(),anyInt());long id=createKnowledge(config());publishKnowledge(id);when(ai.complete(anyString(),anyList(),anyInt())).thenAnswer(i->{knowledge.status(manager,id,key(),state(2,"STOPPED"));return new DeepSeekClient.Completion("must not be returned","synthetic-model",1,1);});assertEquals(404,code(()->knowledge.answer(owner,request)));}
}
